{
  "packet_id": "H6-T02-3",
  "claim_id": "C034",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C034.component",
    "value": "If the tested concurrency change worsens outcomes, the original setting should be restored.",
    "scope": "Conditional response to worsening; the mapping does not specify a worsening threshold here.",
    "provenance": {
      "refs": [
        {
          "source_id": "P030",
          "role": "SUPPORT"
        },
        {
          "source_id": "P009",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P030 supplies the worsening condition and restoration decision; P009 identifies the tested concurrency change."
    }
  },
  "signal_basis": {
    "component_id": "C034.signal_basis",
    "value": "After a known step from baseline concurrency c0 to lower concurrency c1, export outcomes worsen, assessed against baseline and any unchanged comparison pool.",
    "scope": "Assumed observation from the proposed test, limited to the tested cohort, concurrency range, versions, and operating conditions.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        },
        {
          "source_id": "P030",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        },
        {
          "source_id": "P040",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans establish the perturbation, comparison basis, worsening signal, proposed rather than already observed status, and limits of application."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C034.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The bounded restoration decision is warranted under the assumed worsening signal without an additional unresolved empirical relation."
    }
  },
  "rationale": "Given the stipulated worsening from the tested concurrency change, restoring the prior setting is a warranted response to an adverse experiment. The claim requires neither identification of the underlying mechanism nor proof that restoration will resolve every export delay.",
  "uncertainty": "P030 leaves the magnitude and precision needed to classify worsening unspecified. This limits application to ambiguous results, but does not defeat the conditional claim when worsening is assumed.",
  "anomalies": []
}
